def flatten_iter(obj, sep='.'):
    out, stack = {}, [('', obj)]
    while stack:
        prefix, val = stack.pop()
        if isinstance(val, dict):
            for k, v in val.items():
                stack.append((f'{prefix}{sep}{k}' if prefix else str(k), v))
        else:
            out[prefix] = val
    return out

