import re
from collections import Counter

LOG_RE = re.compile(r'"[A-Z]+ [^"]*" (\d{3}) ')

def count_status_codes(path):
    """Return {status_code: count} parsed from an Apache-style access log."""
    counts = Counter()
    with open(path, 'r') as f:
        for line in f:
            match = LOG_RE.search(line)
            if match:
                counts[match.group(1)] += 1
    return dict(counts)

